 function leaveReview(r){const name=staffProfiles.find(p=>p.id===(r.staffId||'maya'))?.name||'Maya';return row('staffLabel',esc(name))+row('venue',t('venueA'))+row('from',dateText(r.start))+row('until',dateText(r.end))+row('status',t('pendingReview'))+row('reason',t(r.reasonKey||(r.medical?'medicalSampleReason':'leaveSampleReason')))+(r.medical?small('medicalEvidenceDemo'):'')+(r.escalated?small('leaveEscalationNotice'):'')+reasonField('leave-'+r.id)+button('approveLeaveAction',`data-typed-decision="approveLeave" data-item="leave-${r.id}"`)+button('rejectLeaveAction',`data-typed-decision="rejectLeave" data-item="leave-${r.id}"`);}
 function syncActions(){for(const r of customer.allRecords()){if(r.status==='completed'&&!r.spendId){r.spend=r.spend??(r.reservationKind==='room'?1688:r.reservationKind==='table'?0:r.type==='packageA'?1288:r.type==='packageB'?2500:300);r.spendId='spend-'+r.id;spend.push({id:r.spendId,customerId:r.customerId||customers[0].id,date:r.date,components:[{key:r.type,amount:r.spend}],total:r.spend,staffId:r.staffId,approvedBy:r.approvedBy,start:r.startedAt,end:r.endedAt,durationMinutes:r.durationMinutes,blocks:r.blocks,table:r.table});}}for(const h of spend){const r=customer.allRecords().find(r=>r.spendId===h.id);if(r?.assignmentSessions&&r.changeHistory?.length&&r.status==='completed'){const sessions=r.assignmentSessions.filter(a=>a.startedAt&&a.endedAt&&!a.cancelledAt);h.components=[...(r.reservationKind==='room'?[{key:'roomReservation',amount:1688}]:[]),...sessions.map(a=>({key:r.type==='packageA'||r.type==='packageB'?r.type:'ordinary',amount:a.amount||0}))];h.services=sessions.map(a=>({parentBookingId:r.id,type:r.type==='packageA'||r.type==='packageB'?r.type:'ordinary',staffId:a.staffId,staff:staffProfiles.find(p=>p.id===a.staffId)?.name,approvedBy:r.approvedBy||'Daniel Tan',startedAt:a.startedAt,endedAt:a.endedAt,durationMinutes:Math.floor((Date.parse(a.endedAt)-Date.parse(a.startedAt))/60000),blocks:a.hours,price:a.amount,table:r.table}));h.total=r.spend;}}if(!['manager','admin'].includes(s.role))return;const live=sourceActions(),ids=new Set(live.map(x=>x.id));for(const x of live){const previous=archive.get(x.id);if(!previous)archive.set(x.id,{...x,resolved:false,audit:[]});else if(!previous.reopened){if(previous.resolved){const historyId=x.id+'-history-'+(++sessionSequence);archive.set(historyId,{...previous,id:historyId,audit:[...previous.audit]});previous.audit=[];delete previous.resolvedAt;delete previous.outcome;}Object.assign(previous,x,{resolved:false});}}for(const [id,item] of archive)if(canSee(item)&&!item.resolved&&!item.reopened&&!ids.has(id)){finishAction(item,'actionCompleted');} }

