 function usernameSuggestions(value){const prefix=String(value||'').trim().replace(/^@/,'').toLowerCase();return prefix?customers.filter(c=>c.username.toLowerCase().startsWith(prefix)).sort((a,b)=>a.username.toLowerCase().localeCompare(b.username.toLowerCase(),'en')):[];}
