 function lookupKeydown(e){if(e.target.id!=='customer-lookup'||s.role!=='manager'||modal!=='manual')return false;const matches=usernameSuggestions(scanText);if(e.key==='Escape'&&lookupOpen){e.preventDefault();lookupOpen=false;lookupIndex=-1;paintUsernameSuggestions();return true;}if(['ArrowDown','ArrowUp'].includes(e.key)&&matches.length){e.preventDefault();lookupOpen=true;lookupIndex=lookupIndex<0?(e.key==='ArrowDown'?0:matches.length-1):(lookupIndex+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;paintUsernameSuggestions();document.getElementById('customer-suggestion-'+lookupIndex)?.scrollIntoView?.({block:'nearest'});return true;}if(e.key==='Enter'&&lookupOpen&&lookupIndex>=0&&matches[lookupIndex]){e.preventDefault();selectUsername(matches[lookupIndex].id);return true;}if(e.key==='Tab'){lookupOpen=false;lookupIndex=-1;paintUsernameSuggestions();}return false;}
