 function findCustomer(value){const raw=value.trim();return customers.find(c=>raw==='66MM-CUSTOMER:'+c.id||raw.replace(/^@/,'').toLowerCase()===c.username.toLowerCase());}
 function stopScan(){scanGeneration++;scanStream?.getTracks().forEach(t=>t.stop());scanStream=null;}
 async function scan(){if(!navigator.mediaDevices?.getUserMedia||!window.BarcodeDetector){customer.toast('cameraUnavailable');return;}const gen=++scanGeneration;try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(!modal||gen!==scanGeneration){stream.getTracks().forEach(t=>t.stop());return;}scanStream=stream;const video=document.getElementById('customer-scan-video');video.hidden=false;video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});const read=async()=>{if(!scanStream||gen!==scanGeneration)return;try{const codes=await detector.detect(video);if(codes[0]){scanText=codes[0].rawValue;stopScan();manualCustomer=findCustomer(scanText);if(!manualCustomer)customer.toast('customerNotFound');paintModal();return;}}catch{}setTimeout(read,250);};read();}catch{stopScan();customer.toast('cameraUnavailable');}}
