 function pickers(){document.querySelectorAll('input[type="date"]').forEach(el=>{el.classList.add('shared-calendar');el.lang=s.lang==='zh'?'zh-Hans':s.lang;});document.querySelectorAll('input[type="time"],input[type="datetime-local"]').forEach(el=>{if(el.dataset.pickerReady)return;el.dataset.pickerReady='true';const isDate=el.type==='datetime-local',raw=el.value||'22:00',time=isDate?raw.slice(11):raw;el.dataset.originalType=el.type;el.type='hidden';if(!el.id)el.id='picker-'+(++sessionSequence);const h=Number(time.split(':')[0])||0,m=Number(time.split(':')[1])||0;const group=document.createElement('div');group.className='shared-time-picker';group.dataset.input=el.id;group.innerHTML=(isDate?`<input type="date" class="shared-calendar" data-picker-date="${el.id}" value="${raw.slice(0,10)}">`:'')+`<div class="time-wheels">${[['hour24',Array.from({length:24},(_,i)=>i),h,'hoursWheel'],['minute',Array.from({length:60},(_,i)=>i),m,'minutesWheel']].map(([key,values,current,label])=>`<div class="wheel-column"><span>${t(label)}</span><div class="time-wheel" role="listbox" tabindex="0" aria-label="${t(label)}" data-universal-wheel="${key}" data-picker-id="${el.id}">${values.map(v=>`<button type="button" role="option" aria-selected="${v===current}" data-universal-option="${key}" data-picker-id="${el.id}" data-value="${v}">${key==='period'?t(v):String(v).padStart(2,'0')}</button>`).join('')}</div></div>`).join('')}</div>`;el.insertAdjacentElement('afterend',group);group.querySelectorAll('.time-wheel').forEach(w=>{const selected=w.querySelector('[aria-selected="true"]');if(selected)w.scrollTop=selected.offsetTop-w.clientHeight/2+selected.offsetHeight/2;});});}
