 function updateTime(id,key,value){const input=document.getElementById(id);if(!input)return;const isDate=input.dataset.originalType==='datetime-local';const base=input.value|| (isDate?dayAgo(0)+'T22:00':'22:00');const parts=(isDate?base.slice(11):base).split(':');let h=Number(parts[0]),m=Number(parts[1]);if(key==='hour24')h=Number(value);if(key==='hour')h=Number(value)%12+(h>=12?12:0);if(key==='minute')m=Number(value);if(key==='period')h=h%12+(value==='pm'?12:0);input.value=(isDate?base.slice(0,10)+'T':'')+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));const el=document.querySelector(`[data-universal-wheel="${key}"][data-picker-id="${id}"]`);el?.querySelectorAll('[role="option"]').forEach(b=>{const selected=b.dataset.value===String(value);b.setAttribute('aria-selected',String(selected));if(selected)el.scrollTo({top:b.offsetTop-el.clientHeight/2+b.offsetHeight/2,behavior:'smooth'});});}
